<?php
namespace App\Http\Controllers; use App\Domain\Articles\{ArticleIndexViewData,ArticleViewData}; use App\Models\ArticleCategory; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; class PublicArticleController extends Controller { public function index(Request $r,ArticleIndexViewData $d):View{$category=$r->integer('category')?:null;return view('articles.index',['articles'=>$d->get(max(1,$r->integer('page',1)),$category),'categories'=>ArticleCategory::where('is_active',true)->orderBy('display_order')->get(['id','name'])]+app(PublicSiteController::class)->sharedViewData($r));} public function show(Request $r,string $article,ArticleViewData $d):View{$x=$d->published($article);if(!$x){abort(404);}return view('articles.show',['article'=>$x,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($r));} }
